   void mainImage(out vec4 fragColor, in vec2 fragCoord) {
       vec2 uv = fragCoord / iResolution.xy;
       vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

       float r = length(p);
       float a = atan(p.y, p.x);

       // Time-based rotation and scaling
       float t = iTime * 0.5;
       a += t * 0.3;
       r *= 1.0 + 0.1 * sin(t * 0.7);

       // Multi-layered spiral/wave pattern
       float pattern1 = sin(a * 6.0 + r * 12.0 - t * 2.0);
       float pattern2 = sin(a * 4.0 - r * 8.0 + t * 1.5);
       float pattern3 = cos(r * 10.0 - t * 3.0 + a * 2.0);

       float combined = (pattern1 + pattern2 + pattern3) / 3.0;

       // Smooth color palette (cosine technique)
       vec3 col = 0.5 + 0.5 * cos(3.0 + combined * 2.0 + t * 0.4 + vec3(0.0, 0.33, 0.67));

       // Vignette and glow
       float vig = 1.0 - smoothstep(0.3, 1.2, r);
       col *= vig;
       col += 0.1 * exp(-r * 3.0) * vec3(0.8, 0.5, 1.0);

       fragColor = vec4(col, 1.0);
   }
